<?php declare(strict_types=1);$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$appName=getenv('APP_NAME')?:'Academic Timetable Optimiser'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Protected blocks · <?= $e($appName) ?></title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-50 text-slate-900"><div class="min-h-screen lg:flex"><aside class="bg-slate-950 text-white lg:w-64"><div class="border-b border-white/10 px-6 py-6"><p class="text-xs uppercase tracking-widest text-cyan-300">Academic planning</p><a href="/" class="mt-2 block text-lg font-semibold"><?= $e($appName) ?></a></div><nav class="flex flex-wrap gap-2 p-4 lg:flex-col"><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/">Overview</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/demand">Courses & units</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/calendar">Academic calendar</a><a aria-current="page" class="rounded-lg bg-white/10 px-3 py-2 text-sm" href="/rules">Protected blocks</a><a class="rounded-lg px-3 py-2 text-sm text-slate-300" href="/week">Week structure</a></nav></aside><main class="min-w-0 flex-1"><header class="border-b bg-white px-6 py-5"><p class="text-sm text-slate-500">Delivery constraints</p><h1 class="text-2xl font-semibold">Protected timetable blocks</h1><p class="mt-1 text-sm text-slate-600">Reserve periods for English/Maths delivery, Wednesday meetings and training, or other fixed commitments.</p></header><div class="mx-auto max-w-5xl space-y-6 px-6 py-8"><?php if($flash):?><div role="status" class="rounded-xl border p-4 text-sm <?= $flash['type']==='success'?'border-emerald-200 bg-emerald-50':'border-rose-200 bg-rose-50' ?>"><?= $e($flash['message']) ?></div><?php endif;?><section class="rounded-xl border bg-white p-5"><h2 class="font-semibold">Add protected period</h2><form method="post" action="/protected-blocks/save" class="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><label class="text-sm">Name<input required maxlength="120" name="name" placeholder="Wednesday staff development" class="mt-1 block w-full rounded-lg border px-3 py-2"></label><label class="text-sm">Type<select name="block_type" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="english_maths">English / Maths</option><option value="meetings_training">Meetings and training</option><option value="custom">Other protected time</option></select></label><label class="text-sm">Applies to<select name="course_scope" class="mt-1 block w-full rounded-lg border px-3 py-2"><option value="all_courses">All courses</option><option value="vocational_courses">Vocational courses only</option></select></label><label class="text-sm">Day<select required name="week_day_id" class="mt-1 block w-full rounded-lg border px-3 py-2"><?php foreach($days as $d):?><option value="<?= (int)$d['id']?>"><?= $e($d['name'])?></option><?php endforeach;?></select></label><label class="text-sm">Period<select required name="time_slot_id" class="mt-1 block w-full rounded-lg border px-3 py-2"><?php foreach($slots as $s):?><option value="<?= (int)$s['id']?>"><?= $e($s['label'])?> (<?= $e(substr($s['starts_at'],0,5))?>–<?= $e(substr($s['ends_at'],0,5))?>)</option><?php endforeach;?></select></label><div class="flex items-end"><button class="rounded-lg bg-cyan-700 px-4 py-2 text-sm font-semibold text-white">Add block</button></div></form></section><section class="overflow-hidden rounded-xl border bg-white"><div class="border-b p-4"><h2 class="font-semibold">Configured blocks</h2></div><div class="divide-y"><?php foreach($blocks as $b):?><div class="flex flex-wrap items-center justify-between gap-3 p-4"><div><strong><?= $e($b['name'])?></strong><span class="ml-2 rounded-full bg-slate-100 px-2 py-1 text-xs"><?= $b['course_scope']==='vocational_courses'?'Vocational only':'All courses'?></span><p class="mt-1 text-sm text-slate-600"><?= $e($b['day_name'])?> · <?= $e($b['slot_label'])?> (<?= $e(substr($b['starts_at'],0,5))?>–<?= $e(substr($b['ends_at'],0,5))?>) · <?= $e(str_replace('_',' ',$b['block_type']))?></p></div><form method="post" action="/protected-blocks/delete"><input type="hidden" name="_csrf" value="<?= $e($csrfToken)?>"><input type="hidden" name="id" value="<?= (int)$b['id']?>"><button class="text-sm font-medium text-rose-700">Remove</button></form></div><?php endforeach;?><?php if(!$blocks):?><p class="p-6 text-sm text-slate-500">No protected periods configured yet.</p><?php endif;?></div><p class="border-t bg-amber-50 p-4 text-sm text-amber-900">These rules are stored as timetable constraints. The timetable generation engine still needs to enforce them.</p></section></div></main></div></body></html>
